-      // 64-bit golden ratio constant from boost::hash_combine to spread mixed keys.
-      seed ^= std::hash<int64_t>{}(value) + 0x9e3779b97f4a7c15ULL + (seed << 6) + (seed >> 2);
-    };
-    combine(key.hash0);
-    combine(key.hash1);
-    combine(key.frontend_version);
-    return seed;
-  }
-};
